function flush(){if(!FULL||listBusy())return false;draw(1);refreshCounts();return true} // a click, a focusout out of the list, a popup closed
// only that order's card is drawn again; while the user is in one of its fields (focused, or a comment that differs from
// its saved text) it waits in PEND and is drawn on blur, or by the full draw a save / revert does. Not on this page: counts only.
var PEND={};
function cardBusy(el){var a=R.activeElement,d=DP&&dpInput();if(a&&el.contains(a)||d&&el.contains(d))return true;return[].some.call(el.querySelectorAll('[data-orig]'),function(t){return t.value.trim()!==(t.dataset.orig||'').trim()})}
function cssEsc(v){return window.CSS&&window.CSS.escape?window.CSS.escape(String(v)):String(v)} // window.CSS: this block's own CSS is the style text
function redrawCard(id){var el=$('list').querySelector('.card[data-o="'+cssEsc(id)+'"]');if(!el){delete PEND[id];return}if(cardBusy(el)){PEND[id]=1;return}delete PEND[id];
 var t=document.createElement('div');t.innerHTML=OM[id]?card(OM[id]):'';if(t.firstElementChild)el.replaceWith(t.firstElementChild);else el.remove()}
function refreshCounts(){$('cn').textContent=O.filter(function(o){return match(o)}).length;drawChips();var fv=$('fv');if(R.activeElement!==fv)fv.innerHTML=opts(V,S.vendor,'المبتكر: الكل')}
function vcount(o){var m={};o.subs.forEach(function(s){m[s.vendor]=1});return Object.keys(m).length}
function openCount(o){return o.subs.filter(function(s){return OPEN[s.raw]}).length}
// owner batch 2 decision 17 (the settings' «قواعد التأخير» — IbtekrOps.delayRules / orderDelayOf / lineDelayOf, the same as the server's
// _shared/delay.js): the days count from the start point (the confirmation by default — none while not confirmed — or the order's date;
// a line from the same start — the owner 15 Nov: «بناء علي تاريخ التأكيد» —, its maker's notify date only with start «notify»; a line
// closed on the site or «ملغي» has no counter — «مقفول»). The order is «قابل للتأخير» N days before
// the longest making days of its open lines end and «متأخر» once they are past, unless its (base) status stops the counter; a line
// against its own making days (s.lead: the product's own, else the maker's «مدة التجهيز», else the settings' default).
function XO(){return window.IbtekrOps}
var DR=null;function RULES(){if(!DR){var S0=window.IBSettings;DR=S0&&S0.delayRules?S0.delayRules():XO().delayRules(null)}return DR}
function cage(o){if(RULES().start==='order')return daysSince(o.date);return XO().isConfirmed(o.cf)?daysSince(o.confAt||o.cdate||o.date):null}
function lineOpen(s){return !!OPEN[s.raw]&&!s.pulled&&s.ss!=='ملغي'}
function maxLead(o){var m=null;o.subs.forEach(function(s){if(lineOpen(s)){var l=slead(s);if(m==null||l>m)m=l}});return m}
function ostate(o){return XO().orderDelayOf({status:o.st,elapsed:cage(o),maxLead:maxLead(o)},RULES())}
function late(o){return ostate(o)==='late'}
function risk(o){return ostate(o)==='risk'}
function dstate(o){return ostate(o)}
function slead(s){return s.leadSrc==='default'||!Number(s.lead)?RULES().lead:Number(s.lead)}
function sel(o,s){return RULES().start==='notify'?(s.exp?daysSince(s.exp):null):cage(o)}
function sstate(o,s){return lineOpen(s)?XO().lineDelayOf(sel(o,s),slead(s),true,RULES()):'ok'}
function sbadge(s,sl){return lineOpen(s)?dbadge(sl):'<span class="badge s-proc" data-closed title="'+(s.ss==='ملغي'?'المنتج ملغي':'الأوردر الفرعي مقفول على الموقع ('+esc(SITE_ST[s.raw]||s.raw||'—')+')')+' — مالوش عدّاد تأخير">مقفول'+ic('xc')+'</span>'}
var SITE_ST={completed:'مكتمل',cancelled:'ملغي',refunded:'مسترجع',failed:'فشل',trash:'المهملات','checkout-draft':'مسودة'};
function startTxt(){var st=RULES().start;return st==='notify'?'العدّاد بيحسب الأيام من تاريخ تبليغ المبتكر على مدة التصنيع (بتاعة المنتج، وإلا بتاعة المبتكر) · من غير تاريخ تبليغ مالوش عدّاد':'العدّاد بيحسب الأيام من '+(st==='order'?'تاريخ الأوردر':'تاريخ تأكيد الأوردر')+' على مدة التصنيع (بتاعة المنتج، وإلا بتاعة المبتكر) · نقطة البداية من الإعدادات › المبتكرين'}
function leadTxt(s){return'مدة التصنيع: '+slead(s)+' يوم'+(s.leadSrc==='product'?' (المنتج)':s.leadSrc==='maker'?' (المبتكر)':'')}
function scount(o,s){var e=lineOpen(s)?sel(o,s):null,n=slead(s);return{e:e,n:n,t:e==null?'—':Math.min(e,99)+'/'+n,pct:e==null?0:Math.min(e/n,1)*100}}
var DB={risk:['s-warn','قابل للتأخير','clock','#f08a1c'],late:['s-err','متأخر','alert','#da0001'],ok:['s-ok','غير متأخر','check','#39ac00']};
function dbadge(k){var d=DB[k];return'<span class="badge '+d[0]+'">'+d[1]+ic(d[2])+'</span>'}
var SEL={}; // التحديد الجماعي (owner 31 Oct): id → true
function pageList(cur,n){if(n<=7){var all=[];for(var i=1;i<=n;i++)all.push(i);return all}var set=[1,n,cur-1,cur,cur+1];if(cur<=4)set.push(2,3,4,5);if(cur>=n-3)set.push(n-4,n-3,n-2,n-1);set=set.filter(function(x,i){return x>=1&&x<=n&&set.indexOf(x)===i}).sort(function(x,y){return x-y});var out=[];set.forEach(function(x,i){if(i&&x-set[i-1]>1)out.push('…');out.push(x)});return out}
var SIZES=[25,50,100];/* owner 19 Nov: «اتحكم في عدد الصفوف يبقي 25 او 50 او 100» — remembered in this browser */function sizeOf(){try{var v=+localStorage.getItem('ib.orders.size');return SIZES.indexOf(v)>=0?v:25}catch(e){return 25}}
var S={q:'',st:'الكل',deliv:'',conf:'',vendor:'',vc:'',sort:'new',page:1,size:sizeOf(),open:{},edit:null,fb:{op:'and',items:[]}};
function sorted(a){var r=a.slice();
 if(S.sort==='new')r.sort(function(x,y){return x.date<y.date?1:x.date>y.date?-1:(+y.id)-(+x.id)});
 if(S.sort==='old')r.sort(function(x,y){return x.date>y.date?1:x.date<y.date?-1:(+x.id)-(+y.id)});
 if(S.sort==='val')r.sort(function(x,y){return y.tot-x.tot});
 if(S.sort==='late')r.sort(function(x,y){return(late(y)?1:0)-(late(x)?1:0)||(y.age-x.age)});
 return r}
function match(o,skipStatus){
 var q=S.q.trim().toLowerCase();
 if(q){var h=(o.id+' IB-'+o.id+' '+o.name+' '+o.phone).toLowerCase();if(h.indexOf(q)<0)return false}
 if(!skipStatus&&S.st!=='الكل'&&SV(o)!==S.st)return false;
 if(S.deliv&&dstate(o)!==S.deliv)return false;
 if(S.conf&&o.cf!==S.conf)return false;
 if(S.vendor&&!o.subs.some(function(s){return s.vendor===S.vendor}))return false;
 if(S.vc){var n=vcount(o);if(S.vc==='2'?n<2:n!==1)return false}
 if(S.fb.items.length&&!fbEval(S.fb,o))return false;
 return true}
