var DEL_REASONS=['إلغاء من العميل','خامات غير متوفرة','تعديل من العميل','أوردر مكرر'];
function removeOrder(id){id=String(id);var i=O.findIndex(function(o){return o.id===id});if(i<0)return false;O.splice(i,1);delete OM[id];delete SEL[id];if(DET&&DET.id===id)DET.close();if(EDT&&EDT.id===id)EDT.close();draw(1);return true}
// the reason dialog of «مسح» — one order or the selection (decision 53): title, the note under the reason, the button; onOk(reason, button, close)
